    cargo jackioh fuzz --regress > /tmp/regress-after.txt
    cargo jackioh fuzz --seeds 200 --json > /tmp/fuzz-after.json
    diff /tmp/regress-before.txt /tmp/regress-after.txt
    jq -S 'del(.checkpoint.slowestMs)' /tmp/fuzz-before.json > /tmp/a.json
    jq -S 'del(.checkpoint.slowestMs, .coverage)' /tmp/fuzz-after.json > /tmp/b.json
    diff /tmp/a.json /tmp/b.json
    cargo jackioh fuzz --seeds 200
